79	func reconLedger(t *testing.T) (*Ledger, string) {
80		t.Helper()
81		path := newTestLedger(t, []BalanceInit{
82			{Account: "aa-1", Asset: "usdc", Balance: math.MaxInt64},
83			{Account: "aa-2", Asset: "eth", Balance: 100},
84		})
85		l := openOrFail(t, path)
86		// p1: aa-1/usdc amount=1000 fee=3 charged=1003；p2: aa-2/eth amount=10 fee=0 charged=10。
87		res, err := l.Submit(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{
88			{ID: "p1", Account: "aa-1", Paymaster: "pm", Asset: "usdc", Amount: i64p(1000), Nonce: 1, State: "pending"},
89			{ID: "p2", Account: "aa-2", Asset: "eth", Amount: i64p(10), State: "pending"},
90		}})
91		if err != nil {
92			t.Fatalf("submit: %v", err)
93		}
94		if got := statuses(res); got[0] != StatusSettled || got[1] != StatusSettled {
95			t.Fatalf("setup statuses=%v", got)
96		}
97		// r1 退回 p1。
98		rr, err := l.Refund(RefundBatch{Refunds: []RefundRequest{
99			{ID: "r1", SettlementID: "p1", Reason: "cancel"},
100		}})
101		if err != nil {
102			t.Fatalf("refund: %v", err)
103		}
104		if rr.Results[0].Status != StatusRefundSuccess {
105			t.Fatalf("setup refund=%s", rr.Results[0].Status)
106		}
107		return l, path
108	}
