111		l, _ := reconLedger(t)
112	
113		entries, err := ParseReconcileRequest([]byte(`{"entries":[
114		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003},
115		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":1,"charged":11},
116		  {"kind":"payment","id":"ghost","account":"aa-1","asset":"usdc","amount":5,"fee":0,"charged":5},
117		  {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"},
118		  {"kind":"refund","id":"rX","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p-wrong"},
119		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":0,"charged":10}
120		]}`))
121		if err != nil {
122			t.Fatalf("parse: %v", err)
123		}
124		rep, err := l.ReconcileFlow(entries)
125		if err != nil {
126			t.Fatalf("reconcile: %v", err)
127		}
128	
129		wantStatus := []string{
130			ReconMatched,         // 0: p1 已退款仍按原扣款核对
131			ReconDuplicate,       // 1: p2 与索引 5 同编号，整组重复（不判字段差异）
132			ReconMissingInLedger, // 2: ghost
133			ReconMatched,         // 3: r1
134			ReconMissingInLedger, // 4: rX 在账本退款编号中不存在
135			ReconDuplicate,       // 5: p2 重复组
136		}
137		for i, r := range rep.Results {
138			if r.Status != wantStatus[i] {
139				t.Fatalf("result %d: got %s want %s (%+v)", i, r.Status, wantStatus[i], r)
140			}
141		}
142	
143		// 重复组两条都带全部输入位置 [1,5]。
144		for _, i := range []int{1, 5} {
145			pos := rep.Results[i].Positions
146			if len(pos) != 2 || pos[0] != 1 || pos[1] != 5 {
147				t.Fatalf("result %d positions=%v", i, pos)
148			}
149			if len(rep.Results[i].Diffs) != 0 {
150				t.Fatalf("duplicate must carry no diffs: %+v", rep.Results[i].Diffs)
151			}
152		}
153	
154		// p2 是重复组，账本记录不列入缺失；ghost 是流水外项，只出现在逐条结果。
155		// 唯一未覆盖的账本记录：无（p1/r1 命中，p2 重复抑制）。
156		if len(rep.MissingPayments) != 0 || len(rep.MissingRefunds) != 0 {
157			t.Fatalf("want no missing, got payments=%+v refunds=%+v", rep.MissingPayments, rep.MissingRefunds)
158		}
159	
160		// 已退款付款的匹配结果带退款关联。
161		if rep.Results[0].Record == nil || rep.Results[0].Record.RefundID != "r1" {
162			t.Fatalf("matched p1 must link refund r1: %+v", rep.Results[0].Record)
163		}
164		// 退款匹配结果带原付款编号。
165		if rep.Results[3].Record == nil || rep.Results[3].Record.SettlementID != "p1" {
166			t.Fatalf("matched r1 must link settlement p1: %+v", rep.Results[3].Record)
167		}
168	}
