285	func TestReconcileTotalsAndNetDiff(t *testing.T) {
286		l, _ := reconLedger(t)
287		// 账本：usdc 扣款 1003/退款 1003/净 0；eth 扣款 10/退款 0/净 10。
288		// 流水：usdc 扣款 1003（p1 匹配），退款只来一笔 ghost 500（账本外）；
289		//       eth 扣款 10（p2）。再加一笔账本外资产 jpy。
290		entries, _ := ParseReconcileRequest([]byte(`{"entries":[
291		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003},
292		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":0,"charged":10},
293		  {"kind":"refund","id":"g1","account":"aa-1","asset":"usdc","amount":500,"fee":0,"charged":500,"settlement_id":"p9"},
294		  {"kind":"payment","id":"x1","account":"aa-9","asset":"jpy","amount":7,"fee":0,"charged":7}
295		]}`))
296		rep, err := l.ReconcileFlow(entries)
297		if err != nil {
298			t.Fatalf("reconcile: %v", err)
299		}
300	
301		findRow := func(rows []ReconTotalRow, acct, asset string) ReconTotalRow {
302			t.Helper()
303			for _, r := range rows {
304				if r.Account == acct && r.Asset == asset {
305					return r
306				}
307			}
308			t.Fatalf("row %s/%s not found in %+v", acct, asset, rows)
309			return ReconTotalRow{}
310		}
311		findDiff := func(acct, asset string) ReconNetDiff {
312			t.Helper()
313			for _, r := range rep.NetDiff {
314				if r.Account == acct && r.Asset == asset {
315					return r
316				}
317			}
318			t.Fatalf("diff %s/%s not found in %+v", acct, asset, rep.NetDiff)
319			return ReconNetDiff{}
320		}
321	
322		// 账本侧。
323		usdcL := findRow(rep.Totals.Ledger, "aa-1", "usdc")
324		if usdcL.ChargedTotal != "1003" || usdcL.RefundedTotal != "1003" || usdcL.NetCharged != "0" {
325			t.Fatalf("ledger usdc=%+v", usdcL)
326		}
327		ethL := findRow(rep.Totals.Ledger, "aa-2", "eth")
328		if ethL.ChargedTotal != "10" || ethL.RefundedTotal != "0" || ethL.NetCharged != "10" {
329			t.Fatalf("ledger eth=%+v", ethL)
330		}
331		// 流水侧：jpy 只在流水出现；usdc 净扣款 = 1003-500 = 503。
332		usdcF := findRow(rep.Totals.Flow, "aa-1", "usdc")
333		if usdcF.ChargedTotal != "1003" || usdcF.RefundedTotal != "500" || usdcF.NetCharged != "503" {
334			t.Fatalf("flow usdc=%+v", usdcF)
335		}
336		jpyF := findRow(rep.Totals.Flow, "aa-9", "jpy")
337		if jpyF.NetCharged != "7" {
338			t.Fatalf("flow jpy=%+v", jpyF)
339		}
340		if len(rep.Totals.Ledger) != 2 || len(rep.Totals.Flow) != 3 {
341			t.Fatalf("row counts ledger=%d flow=%d", len(rep.Totals.Ledger), len(rep.Totals.Flow))
342		}
343		// 差额方向为流水减账本。
344		if d := findDiff("aa-1", "usdc"); d.NetChargedDiff != "503" || d.LedgerNetCharged != "0" || d.FlowNetCharged != "503" {
345			t.Fatalf("usdc diff=%+v", d)
346		}
347		if d := findDiff("aa-2", "eth"); d.NetChargedDiff != "0" {
348			t.Fatalf("eth diff=%+v", d)
349		}
350		if d := findDiff("aa-9", "jpy"); d.NetChargedDiff != "7" || d.LedgerNetCharged != "0" {
351			t.Fatalf("jpy diff=%+v", d)
352		}
353		// 行按账户、资产排序。
354		if rep.Totals.Flow[0].Account != "aa-1" || rep.Totals.Flow[1].Account != "aa-2" || rep.Totals.Flow[2].Account != "aa-9" {
355			t.Fatalf("flow rows not sorted: %+v", rep.Totals.Flow)
356		}
357		if rep.NetDiff[0].Account != "aa-1" || rep.NetDiff[len(rep.NetDiff)-1].Account != "aa-9" {
358			t.Fatalf("net_diff not sorted: %+v", rep.NetDiff)
359		}
360	}
